query GetAllWorkspaces {
  workspaces {
    __typename
    workspaceId
    name
    displayName
    config
    workspaceRootPath
    absolutePath
    kind
    isTemp
  }
}

query ListCollaborationRootHistory {
  listCollaborationRootHistory {
    __typename
    ... on AgentOrgRootHistoryObject {
      root_subject_kind
      root_run_id
      created_at
      archived_at
      is_active
      summary
      org
      __typename
    }
    ... on AgentTeamRootHistoryObject {
      root_subject_kind
      root_run_id
      __typename
    }
  }
}

query GetAgentOrgDefinitions {
  agentOrgDefinitions {
    id
    name
    description
    instructions
    category
    avatarUrl
    revision
    handoffs {
      from
      to
      rules
      __typename
